
import {
  HashRouter,
  Routes,
  Route,
  useLocation,
  Navigate,
} from "react-router-dom";

import {
  ClerkLoaded,
  ClerkLoading,
  SignedIn,
  SignedOut,
  SignIn,
  SignUp,
} from "@clerk/clerk-react";

import Nutrition from "./pages/Nutrition";
import Workout from "./pages/Workout";
import Dashboard from "./pages/Dashboard";
import Navbar from "./components/Navbar";
import Footer from "./components/Footer";
import Feedback from "./pages/Feedback";
import TermsAndConditions from "./pages/TermsAndConditions";
import PrivacyPolicy from "./pages/PrivacyPolicy";
import NotFound from "./pages/NotFound";

const BASE_URL = process.env.PUBLIC_URL || "";
const HOME_URL = `${BASE_URL}/#/`;
const SIGN_IN_URL = `${BASE_URL}/#/sign-in`;
const SIGN_UP_URL = `${BASE_URL}/#/sign-up`;

const centerStyle = {
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  minHeight: "100vh",
  backgroundColor: "#111",
  padding: "20px",
};

const clerkTheme = {
  layout: {
    logoPlacement: "inside",
    logoImageUrl: `${BASE_URL}/assets/img/brandlogo.png`,
  },
  variables: {
    colorPrimary: "#ff7a18",
    colorBackground: "#151515",
    colorText: "#ffffff",
    colorInputBackground: "#1a1a1a",
    colorInputText: "#ffffff",
    borderRadius: "8px",
  },
  elements: {
    card: {
      backgroundColor: "#000000",
      border: "1px solid #333",
      borderRadius: "12px",
    },
    headerTitle: {
      color: "#ff7a18",
    },
    formButtonPrimary: {
      backgroundColor: "#ff7a18",
      color: "#000000",
    },
  },
};

function ProtectedRoute({ children }) {
  return (
    <>
      <SignedIn>{children}</SignedIn>
      <SignedOut>
        <Navigate to="/sign-in" replace />
      </SignedOut>
    </>
  );
}

function AuthPage({ type }) {
  return (
    <div style={centerStyle}>
      <SignedIn>
        <Navigate to="/" replace />
      </SignedIn>

      <SignedOut>
        {type === "sign-in" ? (
          <SignIn
            routing="virtual"
            signUpUrl={SIGN_UP_URL}
            fallbackRedirectUrl={HOME_URL}
            appearance={clerkTheme}
          />
        ) : (
          <SignUp
            routing="virtual"
            signInUrl={SIGN_IN_URL}
            fallbackRedirectUrl={HOME_URL}
            appearance={clerkTheme}
          />
        )}
      </SignedOut>
    </div>
  );
}

function AppContent() {
  const location = useLocation();

  const isAuthPage =
    location.pathname.startsWith("/sign-in") ||
    location.pathname.startsWith("/sign-up");

  return (
    <>
      {!isAuthPage && <Navbar />}

      <main>
        <ClerkLoading>
          <div style={centerStyle}>
            <p style={{ color: "#ff7a18" }}>
              Loading authentication...
            </p>
          </div>
        </ClerkLoading>

        <ClerkLoaded>
          <Routes>
            <Route path="/" element={<Dashboard />} />

            <Route
              path="/nutrition"
              element={
                <ProtectedRoute>
                  <Nutrition />
                </ProtectedRoute>
              }
            />

            <Route
              path="/workout"
              element={
                <ProtectedRoute>
                  <Workout />
                </ProtectedRoute>
              }
            />

            <Route
              path="/feedback"
              element={
                <ProtectedRoute>
                  <Feedback />
                </ProtectedRoute>
              }
            />

            <Route
              path="/termsandconditions"
              element={
                <ProtectedRoute>
                  <TermsAndConditions />
                </ProtectedRoute>
              }
            />

            <Route
              path="/privacypolicy"
              element={
                <ProtectedRoute>
                  <PrivacyPolicy />
                </ProtectedRoute>
              }
            />

            <Route
              path="/sign-in/*"
              element={<AuthPage type="sign-in" />}
            />

            <Route
              path="/sign-up/*"
              element={<AuthPage type="sign-up" />}
            />

            <Route path="*" element={<NotFound />} />
          </Routes>
        </ClerkLoaded>
      </main>

      {!isAuthPage && <Footer />}
    </>
  );
}

export default function App() {
  return (
    <HashRouter>
      <AppContent />
    </HashRouter>
  );
}
