
import React, { useState, useEffect } from "react";
import { Link, useLocation } from "react-router-dom";
import {
  SignedOut,
  SignedIn,
  UserButton,
} from "@clerk/clerk-react";

const Navbar = () => {
  const [menuOpen, setMenuOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(
    window.innerWidth < 992
  );
  const [hover, setHover] = useState(false);

  const location = useLocation();

  // GitHub Pages compatible image path
  const logoPath = `${process.env.PUBLIC_URL}/assets/img/brandlogow.png`;

  // Responsive screen detection
  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 992;
      setIsMobile(mobile);

      if (!mobile) {
        setMenuOpen(false);
      }
    };

    window.addEventListener("resize", handleResize);

    return () => {
      window.removeEventListener("resize", handleResize);
    };
  }, []);

  // Close mobile menu when route changes
  useEffect(() => {
    setMenuOpen(false);
  }, [location.pathname]);

  // Prevent background scrolling when menu is open
  useEffect(() => {
    document.body.style.overflow =
      menuOpen && isMobile ? "hidden" : "";

    return () => {
      document.body.style.overflow = "";
    };
  }, [menuOpen, isMobile]);

  const overlayStyle = {
    display: menuOpen ? "block" : "none",
    position: "fixed",
    inset: 0,
    backgroundColor: "rgba(0,0,0,0.6)",
    zIndex: 998,
  };

  const menuStyle = {
    position: "fixed",
    top: 0,
    left: menuOpen ? "0" : "-260px",
    width: "260px",
    maxWidth: "85vw",
    height: "100dvh",
    backgroundColor: "rgba(0,0,0,0.98)",
    padding: "20px",
    zIndex: 999,
    transition: "left 0.3s ease",
    borderRight: "2px solid #ff7a18",
    overflowY: "auto",
    boxSizing: "border-box",
  };

  const linkStyle = {
    borderTop: "1px solid #333",
    display: "block",
    padding: "12px 0",
    color: "#fff",
    textDecoration: "none",
    fontWeight: "500",
    fontFamily: "Poppins, sans-serif",
  };

  const hamburgerStyle = {
    fontSize: "26px",
    cursor: "pointer",
    color: "#fff",
    display: isMobile ? "block" : "none",
    background: "transparent",
    border: "none",
    padding: "4px 8px",
  };

  const desktopMenuStyle = {
    display: isMobile ? "none" : "flex",
    gap: "20px",
    listStyle: "none",
    alignItems: "center",
    margin: 0,
    padding: 0,
    fontFamily: "Poppins, sans-serif",
  };

  const logoStyle = {
    height: isMobile ? "34px" : "42px",
    width: "auto",
    maxWidth: isMobile ? "110px" : "150px",
    objectFit: "contain",
    display: "block",
  };

  const headerStyle = {
    position: "absolute",
    top: 0,
    left: 0,
    width: "100%",
    padding: isMobile
      ? "12px 18px"
      : "12px 30px",
    backgroundColor: "#00000072",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    zIndex: 100,
    fontFamily: "Poppins, sans-serif",
    boxSizing: "border-box",
    minHeight: isMobile ? "62px" : "72px",
  };

  const navLinks = [
    { name: "Home", path: "/" },
    { name: "Nutrition", path: "/nutrition" },
    { name: "Workout", path: "/workout" },
    { name: "Feedback", path: "/feedback" },
  ];

  return (
    <>
      <style>
        {`
          .fitman-nav-link {
            color: #fff;
            text-decoration: none;
            font-weight: 500;
            font-family: Poppins, sans-serif;
            transition: color 0.3s ease;
          }

          .fitman-nav-link:hover {
            color: #ff7a18 !important;
          }

          .fitman-nav-link.active {
            color: #ff7a18;
          }

          .fitman-signin {
            text-decoration: none;
            border-radius: 2px;
            transition: all 0.3s ease;
          }

          .fitman-signin:hover {
            background-color: #ff7a18 !important;
            color: #fff !important;
          }
        `}
      </style>

      {/* Mobile menu overlay */}
      {menuOpen && (
        <div
          style={overlayStyle}
          onClick={() => setMenuOpen(false)}
          aria-hidden="true"
        />
      )}

      {/* Mobile sidebar */}
      <aside
        style={menuStyle}
        aria-label="Mobile navigation"
        aria-hidden={!menuOpen}
        inert={!menuOpen}
      >
        <button
          type="button"
          onClick={() => setMenuOpen(false)}
          aria-label="Close menu"
          style={{
            display: "block",
            marginLeft: "auto",
            color: "#ff7a18",
            fontSize: "26px",
            cursor: "pointer",
            background: "transparent",
            border: "none",
          }}
        >
          &times;
        </button>

        <ul
          style={{
            listStyle: "none",
            padding: 0,
            margin: "20px 0",
          }}
        >
          <SignedIn>
            <li style={{ marginBottom: "20px" }}>
              <UserButton
                afterSignOutUrl={`${process.env.PUBLIC_URL}/#/`}
              />
            </li>
          </SignedIn>

          {navLinks.map((item) => (
            <li key={item.path}>
              <Link
                className={`fitman-nav-link ${
                  location.pathname === item.path
                    ? "active"
                    : ""
                }`}
                style={linkStyle}
                to={item.path}
                onClick={() => setMenuOpen(false)}
              >
                {item.name === "Nutrition"
                  ? "Nutrition Tracker"
                  : item.name === "Workout"
                  ? "Workout Tracker"
                  : item.name}
              </Link>
            </li>
          ))}

          <SignedOut>
            <li>
              <Link
                className="fitman-nav-link"
                style={linkStyle}
                to="/sign-in"
                onClick={() => setMenuOpen(false)}
              >
                Sign In
              </Link>
            </li>
          </SignedOut>
        </ul>
      </aside>

      {/* Main navbar */}
      <header style={headerStyle}>
        {/* Logo */}
        <Link
          to="/"
          aria-label="FIT MAN Home"
          style={{
            display: "flex",
            alignItems: "center",
            flexShrink: 0,
            textDecoration: "none",
          }}
        >
          <img
            src={logoPath}
            alt="FIT MAN Logo"
            style={logoStyle}
          />
        </Link>

        {/* Desktop navigation */}
        <nav aria-label="Main navigation">
          <ul style={desktopMenuStyle}>
            {navLinks.map((item) => (
              <li key={item.path}>
                <Link
                  className={`fitman-nav-link ${
                    location.pathname === item.path
                      ? "active"
                      : ""
                  }`}
                  to={item.path}
                >
                  {item.name}
                </Link>
              </li>
            ))}

            <li>
              <SignedOut>
                <Link
                  to="/sign-in"
                  className="fitman-signin"
                  onMouseEnter={() => setHover(true)}
                  onMouseLeave={() => setHover(false)}
                  style={{
                    color: hover ? "#fff" : "#ff7a18",
                    backgroundColor: hover
                      ? "#ff7a18"
                      : "transparent",
                    border: "2px solid #ff7a18",
                    padding: "6px 14px",
                    fontFamily: "Poppins, sans-serif",
                    display: "inline-block",
                  }}
                >
                  Sign In
                </Link>
              </SignedOut>

              <SignedIn>
                <UserButton
                  afterSignOutUrl={`${process.env.PUBLIC_URL}/#/`}
                />
              </SignedIn>
            </li>
          </ul>
        </nav>

        {/* Mobile hamburger */}
        <button
          type="button"
          style={hamburgerStyle}
          onClick={() => setMenuOpen(true)}
          aria-label="Open navigation menu"
          aria-expanded={menuOpen}
        >
          &#9776;
        </button>
      </header>
    </>
  );
};

export default Navbar;
